+	history: readonly CheckpointEntry[],
+	runCount: number,
+): CheckpointEntry | undefined {
+	return history.reduce<CheckpointEntry | undefined>((best, entry) => {
+		if (entry.runCount > runCount) {
+			return best;
+		}
+		if (!best || entry.runCount > best.runCount) {
+			return entry;
+		}
